import type { BoostInstantSearchResponse } from "../helpers/boost/types";
import type { SearchAPISearchResult } from "@helpers/search/types";
import { isMobile } from "@helpers/utils";

// Simple scroll locking helpers (avoid external dependency)

import SearchAPIQueryHandler from "@helpers/search/query";
import { SearchAPIConfig, SearchAPISearchResults } from "@helpers/search/types";

class SearchInput extends HTMLElement {
  private searchInput!: HTMLInputElement | null;
  private searchHandler: SearchAPIQueryHandler;
  private apiConfig: SearchAPIConfig;

  private searchButton: HTMLButtonElement | null = null;
  private viewAllButton: HTMLButtonElement | null = null;
  private waitingResults: HTMLElement | null = null;
  private hasResults: HTMLElement | null = null;
  private noResults: HTMLElement | null = null;
  private resultsParent!: HTMLElement | null;
  private suggestionColumn: HTMLElement | null = null;
  private collectionColumn: HTMLElement | null = null;
  private productColumn: HTMLElement | null = null;
  private viewAllTermsEl: HTMLElement | null = null;
  private noResultsTermsEl: HTMLElement | null = null;

  // Header transparency handling
  private headerInner: HTMLElement | null = null;
  private headerWasTransparent = false;
  // Scroll lock state
  private bodyScrollLocked = false;

  private lockBodyScroll() {
    if (this.bodyScrollLocked) return;
    const scrollBarWidth =
      window.innerWidth - document.documentElement.clientWidth;
    document.body.style.overflow = "hidden";
    if (scrollBarWidth > 0) {
      document.body.style.paddingRight = `${scrollBarWidth}px`;
    }
    this.bodyScrollLocked = true;
  }

  private unlockBodyScroll() {
    if (!this.bodyScrollLocked) return;
    document.body.style.overflow = "";
    document.body.style.paddingRight = "";
    this.bodyScrollLocked = false;
  }

  private closeSearchResults() {
    this.resultsParent?.classList.remove("is-open");
    this.classList.remove("is-active");
    this.unlockBodyScroll();
    document.body.classList.remove("search-is-open");
    // Restore header transparency if it was originally transparent
    if (this.headerInner && this.headerWasTransparent) {
      this.headerInner.classList.add("is-transparent");
      this.headerWasTransparent = false;
    }

    // Dispatch custom event for header to listen to
    this.dispatchEvent(
      new CustomEvent("search-input-state-change", {
        detail: { isActive: false },
        bubbles: true,
      }),
    );
  }

  private debouncedSearch!: (query: string) => void;

  constructor() {
    super();

    this.apiConfig = {
      SearchAPISearchOptions: {
        resources: ["query", "collection", "product", "page"],
        unavailable_products: "hide",
        fields: [],
        limit: 4,
      },
    };

    this.searchHandler = new SearchAPIQueryHandler(this.apiConfig);

    // debounce setup
    this.debouncedSearch = this.debounce(
      (query: string) => this.getSearchResults(query),
      300,
    );
  }

  connectedCallback() {
    this.cacheDomElements();
    // Cache header element for transparency toggling
    this.headerInner = document.querySelector(
      ".header__inner",
    ) as HTMLElement | null;
    this.setEventListeners();
    this.setInitialValueFromUrl();
    this.setVisibilityChangeListener();
  }

  cacheDomElements() {
    this.searchInput = this.querySelector("[js-search-input='input']");
    if (!this.searchInput) {
      throw new Error("search input is a required element");
    }
    this.searchButton = this.querySelector("[js-search-input='button']");
    this.viewAllButton = this.querySelector("[js-instant-search='view-all']");
    this.resultsParent = this.querySelector(
      "[js-instant-search='results-parent']",
    );
    this.waitingResults = this.querySelector(
      '[js-instant-search="waiting-input"]',
    );
    this.hasResults = this.querySelector('[js-instant-search="has-results"]');
    this.noResults = this.querySelector('[js-instant-search="no-results"]');
    this.suggestionColumn = this.querySelector(
      "[js-instant-search='suggestions']",
    );
    this.collectionColumn = this.querySelector(
      "[js-instant-search='collections']",
    );
    this.productColumn = this.querySelector("[js-instant-search='products']");
    this.viewAllTermsEl = this.querySelector(
      ".instant-search-results__view-all-text__terms",
    );
    this.noResultsTermsEl = this.querySelector(
      ".instant-search-results__no-results-text__terms",
    );
  }

  setVisibilityChangeListener() {
    // Handle tab switching - don't close search results when tab becomes hidden
    document.addEventListener("visibilitychange", () => {
      if (
        document.hidden &&
        this.resultsParent?.classList.contains("is-open")
      ) {
        // Keep search results open when tab is hidden
        return;
      }
    });
  }

  setEventListeners() {
    this.searchInput?.addEventListener(
      "input",
      this.handleSearchInput.bind(this),
    );

    this.searchInput?.addEventListener("focusin", () => {
      this.resultsParent?.classList.add("is-open");
      const value = this.searchInput?.value || "";
      this.getSearchResults(value);
      // Only show waiting-input container if input is empty
      if (!value.trim()) {
        this.waitingResults?.classList.remove("visually-hidden");
      }
      // Remove transparent header while interacting with search
      if (
        this.headerInner &&
        this.headerInner.classList.contains("is-transparent")
      ) {
        this.headerWasTransparent = true;
        this.headerInner.classList.remove("is-transparent");
      }
      this.lockBodyScroll();
      document.body.classList.add("search-is-open");

      if (isMobile()) {
        this.classList.add("is-active");
      }

      // Dispatch custom event for header to listen to
      this.dispatchEvent(
        new CustomEvent("search-input-state-change", {
          detail: { isActive: true },
          bubbles: true,
        }),
      );
    });

    this.addEventListener("focusout", (event) => {
      const target = event.relatedTarget as Node;
      if (!target) return;

      const isFocusingInsideParent =
        this.resultsParent?.contains(target) || this.contains(target);
      if (isFocusingInsideParent) return;

      // Add a small delay to prevent flickering when switching tabs
      setTimeout(() => {
        // Check if the input is still not focused and no related target
        if (
          !this.searchInput?.matches(":focus") &&
          !this.resultsParent?.contains(document.activeElement)
        ) {
          this.closeSearchResults();
        }
      }, 100);
    });

    this.searchButton?.addEventListener("click", (clickEvent) => {
      if (isMobile()) {
        if (!this.classList.contains("is-active")) {
          return;
        }

        clickEvent.preventDefault();
        if (this.searchInput) {
          this.searchInput.value = "";
          this.searchInput?.blur();
        }
        this.resultsParent?.classList.remove("is-open");
        this.classList.remove("is-active");
        this.unlockBodyScroll();
        document.body.classList.remove("search-is-open");
        this.updateUrlQuery("");
      }
    });

    const closeButton = this.querySelector("[js-instant-search='close']");
    closeButton?.addEventListener("click", () => {
      this.closeSearchResults();
    });

    // Attach reset button event listener directly
    const resetButton = this.querySelector("[js-search-input='reset']");
    if (resetButton) {
      resetButton.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (this.searchInput) {
          this.searchInput.value = "";
          this.resetSuggestions();
          this.updateUrlQuery("");
          this.renderResultsPanel("");
          this.clearExistingSearchResults();
          this.closeSearchResults();
        }
      });
    }

    this.viewAllButton?.addEventListener("click", () => {
      const query = this.searchInput?.value || "";
      window.location.href = `${window.Shopify.routes.root}search?q=${query}`;
    });

    document.addEventListener("click", (event) => {
      const clickedElement = event.target as Node;
      const isClickOutside =
        !this.contains(clickedElement) &&
        !this.resultsParent?.contains(clickedElement);

      if (isClickOutside) {
        this.closeSearchResults();
      }
    });
  }

  private isResultsEmpty(results: SearchAPISearchResults): boolean {
    return !(
      (results.queries && results.queries.length > 0) ||
      (results.pages && results.pages.length > 0) ||
      (results.collections && results.collections.length > 0) ||
      (results.products && results.products.length > 0)
    );
  }

  private highlightSearchTerm(
    element: HTMLElement,
    text: string,
    query: string,
  ) {
    if (!query.trim()) {
      element.innerHTML = text;
      return;
    }

    const queryLower = query.toLowerCase();
    const textLower = text.toLowerCase();
    const queryIndex = textLower.indexOf(queryLower);

    if (queryIndex === -1) {
      element.innerHTML = text;
      return;
    }

    const beforeMatch = text.substring(0, queryIndex);
    const match = text.substring(queryIndex, queryIndex + query.length);
    const afterMatch = text.substring(queryIndex + query.length);

    element.innerHTML = `${beforeMatch}<mark class="search-highlight">${match}</mark>${afterMatch}`;
  }

  private filterAndHighlightSuggestions(query: string) {
    const suggestionsContainer = this.querySelector(
      '[js-instant-search="suggestions"] .instant-search-results__results',
    );
    if (!suggestionsContainer) return;

    const suggestionLinks = suggestionsContainer.querySelectorAll(
      "a[data-suggestion-text]",
    );
    const queryLower = query.toLowerCase().trim();

    suggestionLinks.forEach((link) => {
      const linkElement = link as HTMLElement;
      const originalText =
        linkElement.getAttribute("data-suggestion-text") || "";
      const textSpan = linkElement.querySelector("span") as HTMLElement;

      if (!textSpan) return;

      const textLower = originalText.toLowerCase();

      if (queryLower === "" || textLower.includes(queryLower)) {
        linkElement.style.display = "";
        this.highlightSearchTerm(textSpan, originalText, query);
      } else {
        linkElement.style.display = "none";
      }
    });
  }

  private resetSuggestions() {
    const suggestionsContainer = this.querySelector(
      '[js-instant-search="suggestions"] .instant-search-results__results',
    );
    if (!suggestionsContainer) return;

    const suggestionLinks = suggestionsContainer.querySelectorAll(
      "a[data-suggestion-text]",
    );
    suggestionLinks.forEach((link) => {
      const linkElement = link as HTMLElement;
      linkElement.style.display = "";
      const textSpan = linkElement.querySelector("span") as HTMLElement;
      const originalText =
        linkElement.getAttribute("data-suggestion-text") || "";
      if (textSpan) {
        textSpan.innerHTML = originalText;
      }
    });
  }

  private setColumnVisible(column: HTMLElement | null, visible: boolean): void {
    if (!column) return;
    column.classList.toggle("visually-hidden", !visible);
  }

  renderResultsPanel(
    query: string | undefined,
    results?: BoostInstantSearchResponse | SearchAPISearchResults,
  ) {
    if (!query) {
      this.waitingResults?.classList.remove("visually-hidden");
      this.hasResults?.classList.add("visually-hidden");
      this.noResults?.classList.add("visually-hidden");
      return;
    }

    if (query && !results) {
      this.waitingResults?.classList.add("visually-hidden");
      this.hasResults?.classList.add("visually-hidden");
      this.noResults?.classList.remove("visually-hidden");
      if (this.noResultsTermsEl) this.noResultsTermsEl.textContent = query;
      return;
    }

    const isEmpty = this.isResultsEmpty(results as SearchAPISearchResults);

    if (results && !isEmpty) {
      this.waitingResults?.classList.add("visually-hidden");
      this.hasResults?.classList.remove("visually-hidden");
      this.noResults?.classList.add("visually-hidden");
      if (this.viewAllTermsEl) this.viewAllTermsEl.textContent = query;
    } else if (results && isEmpty) {
      this.waitingResults?.classList.add("visually-hidden");
      this.hasResults?.classList.add("visually-hidden");
      this.noResults?.classList.remove("visually-hidden");
      if (this.viewAllTermsEl) this.viewAllTermsEl.textContent = query;
      if (this.noResultsTermsEl) this.noResultsTermsEl.textContent = query;
    }
  }

  async getSearchResults(query: string) {
    if (!query.trim()) {
      this.renderResultsPanel("");
      return;
    }

    try {
      const results = (await this.searchHandler.executeSearch(
        query,
      )) as SearchAPISearchResults;

      this.renderResultsPanel(query, results);
      this.clearExistingSearchResults();
      this.renderSearchResults(results, query);
    } catch (error: unknown) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error(String(error));
    }
  }

  handleSearchInput(event: Event) {
    const target = event.target as HTMLInputElement;
    const searchValue = target.value;

    // Always show results panel when typing
    this.resultsParent?.classList.add("is-open");

    this.filterAndHighlightSuggestions(searchValue);
    this.updateUrlQuery(searchValue);

    if (searchValue.trim().length >= 3) {
      this.debouncedSearch(searchValue);
    } else if (searchValue.trim().length === 0) {
      // Show default suggestions when input is empty
      this.renderResultsPanel("");
    }
  }

  setInitialValueFromUrl() {
    const urlParams = new URLSearchParams(window.location.search);
    const searchParam = urlParams.get("q");
    if (searchParam) {
      this.setAttribute("query", searchParam);
    }
  }

  updateUrlQuery(searchValue: string) {
    const urlParams = new URLSearchParams(window.location.search);
    if (searchValue.trim() !== "") {
      urlParams.set("q", searchValue);
    } else {
      urlParams.delete("q");
    }
    const newUrl = `${window.location.pathname}?${urlParams.toString()}${window.location.hash}`;
    window.history.pushState({ path: newUrl }, "", newUrl);
  }

  private clearExistingSearchResults(): void {
    const clearColumn = (column: HTMLElement | null) => {
      const container = column?.querySelector(
        ".instant-search-results__results",
      );
      container?.replaceChildren();
    };

    clearColumn(this.suggestionColumn);
    clearColumn(this.collectionColumn);
    clearColumn(this.productColumn);
  }

  private async renderSearchResults(
    results: SearchAPISearchResults,
    searchQuery?: string,
  ): Promise<void> {
    const getItemLabel = (item: unknown): string => {
      const anyItem = item as Record<string, unknown> | null | undefined;
      const label =
        (anyItem?.title as string | undefined) ??
        (anyItem?.text as string | undefined) ??
        (anyItem?.query as string | undefined) ??
        "";
      return label;
    };

    const createLink = (
      item: SearchAPISearchResult,
      iconHTML?: string,
      searchQuery?: string,
    ) => {
      const a = document.createElement("a");
      a.href = item.url;
      a.className = "instant-search-results__result button button--text";

      const label = getItemLabel(item);
      const textSpan = document.createElement("span");
      textSpan.textContent = label;

      if (iconHTML) {
        a.innerHTML = iconHTML;
        a.appendChild(textSpan);
      } else {
        a.appendChild(textSpan);
      }

      // Apply highlighting if search query is provided
      if (searchQuery && searchQuery.trim() && label) {
        this.highlightSearchTerm(textSpan, label, searchQuery);
      }

      return a;
    };

    const renderList = (
      items: SearchAPISearchResult[] | undefined,
      column: HTMLElement | null,
      searchQuery?: string,
    ) => {
      if (!items || !column) return;
      const container = column.querySelector(
        ".instant-search-results__results",
      );
      if (!container) return;

      const iconType = (container as HTMLElement).dataset.iconType;
      const iconHTML =
        iconType && window.themeVars?.icons
          ? (window.themeVars.icons as unknown as Record<string, string>)[
              iconType
            ]
          : undefined;

      items.slice(0, 3).forEach((item) => {
        const label = getItemLabel(item as unknown);
        if (!label) return;
        container.appendChild(createLink(item, iconHTML, searchQuery));
      });
    };

    // Hide all columns by default; make visible when content is rendered
    this.setColumnVisible(this.suggestionColumn, false);
    this.setColumnVisible(this.collectionColumn, false);
    this.setColumnVisible(this.productColumn, false);

    if (results.queries || results.pages) {
      renderList(results.queries, this.suggestionColumn, searchQuery);
      renderList(results.pages, this.suggestionColumn, searchQuery);
      const hasSuggestions = Boolean(
        (results.queries && results.queries.length > 0) ||
          (results.pages && results.pages.length > 0),
      );
      this.setColumnVisible(this.suggestionColumn, hasSuggestions);
    }

    if (results.collections) {
      renderList(results.collections, this.collectionColumn, searchQuery);
      const hasCollections = results.collections.length > 0;
      this.setColumnVisible(this.collectionColumn, hasCollections);
    }

    // Always attempt condensed product fetch so generic terms (e.g. "snow") show products
    if (this.productColumn) {
      const container = this.productColumn.querySelector(
        ".instant-search-results__results",
      );
      if (container) {
        try {
          const query = encodeURIComponent(this.searchInput?.value || "");
          const response = await fetch(
            `${window.Shopify.routes.root}search?view=condensed&q=${query}`,
          );
          if (!response.ok) throw new Error("Failed to fetch condensed view");
          const html = await response.text();
          container.innerHTML = html;
          const hasProducts = container.children.length > 0;
          this.setColumnVisible(this.productColumn, hasProducts);
          // Only force results wrapper visible if condensed view returned content
          if (hasProducts) {
            this.waitingResults?.classList.add("visually-hidden");
            this.hasResults?.classList.remove("visually-hidden");
            this.noResults?.classList.add("visually-hidden");
            if (this.viewAllTermsEl)
              this.viewAllTermsEl.textContent = searchQuery || "";
          }
        } catch (error: unknown) {
          console.error("Error fetching condensed product results", error);
          // Fallback to predictive product list if available
          if (results.products) {
            renderList(results.products, this.productColumn);
            const hasProducts = results.products.length > 0;
            this.setColumnVisible(this.productColumn, hasProducts);
          }
        }
      }
    }
  }

  // generic debounce utility
  private debounce<A extends unknown[]>(
    fn: (...args: A) => unknown,
    delay: number,
  ): (...args: A) => void {
    let timeout: number | undefined;
    return (...args: A) => {
      clearTimeout(timeout);
      timeout = window.setTimeout(() => fn(...args), delay);
    };
  }
}

customElements.define("uwp-search-input", SearchInput);
